2 + c^2)) \\ &= \frac{1}{3}(9R^2 - (a^2 + b^2 + c^2)). \end{align*}  Now, substituting this back into our expression for $AF^2 + BF^2 + CF^2$, we have:  \begin{align*} AF^2 + BF^2 + CF^2 &= 3|\overrightarrow{OG}|^2 - 2\left(\frac{1}{3}(9R^2 - (a^2 + b^2 + c^2))\right) + 3R^2 \\ &= 3|\overrightarrow{OG}|^2 - \frac{2}{3}(9R^2 - (a^2 + b^2 + c^2)) + 3R^2 \\ &= 3|\overrightarrow{OG}|^2 - 6R^2 + \frac{2}{3}(a^2 + b^2 + c^2) + 3R^2 \\ &= 3|\overrightarrow{OG}|^2 - 3R^2 + \frac{2}{3}(a^2 + b^2 + c^2). \end{align*}  Now, we need to find $|\overrightarrow{OG}|^2$.  Using the identity $\overrightarrow{OG} = \frac{1}{3}(\overrightarrow{OA} + \overrightarrow{OB} + \overrightarrow{OC})$, we have:  \begin{align*} |\overrightarrow{OG}|^2 &= \left|\frac{1}{3}(\overrightarrow{OA} + \overrightarrow{OB} + \overrightarrow{OC})\right|^2 \\ &= \frac{1}{9}(|\overrightarrow{OA}|^2 + |\overrightarrow{OB}|^2 + |\overrightarrow{OC}|^2 + 2\overrightarrow{OA} \cdot \overrightarrow{OB} + 2\overrightarrow{OA} \cdot \overrightarrow{OC} + 2\overrightarrow{OB} \cdot \overrightarrow{OC}) \\ &= \frac{1}{9}(3R^2 + 2\overrightarrow{OA} \cdot \overrightarrow{OB} + 2\overrightarrow{OA} \cdot \overrightarrow{OC} + 2\overrightarrow{OB} \cdot \overrightarrow{OC}) \\ &= \frac{1}{9}(3R^2 + 2(3R^2 - \frac{a^2 + b^2 + c^2}{2})) \\ &= \frac{1}{9}(3R^2 + 6R^2 - (a^2 + b^2 + c^2)) \\ &= \frac{1}{9}(9R^2 - (a^2 + b^2 + c^2)). \end{align*}  Substituting this back into our expression for $AF^2 + BF^2 + CF^2$, we have:  \begin{align*} AF^2 + BF^2 + CF^2 &= 3\left(\frac{1}{9}(9R^2 - (a^2 + b^2 + c^2))\right) - 3R^2 + \frac{2}{3}(a^2 + b^2 + c^2) \\ &= \frac{1}{3}(9R^2 - (a^2 + b^2 + c^2)) - 3R^2 + \frac{2}{3}(a^2 + b^2 + c^2) \\ &= 3R^2 - \frac{1}{3}(a^2 + b^2 + c^2) - 3R^2 + \frac{2}{3}(a^2 + b^2 + c^2) \\ &= \frac{1}{3}(a^2 + b^2 + c^2). \end{align*}  Therefore, $AF^2 + BF^2 + CF^2 = \frac{1}{3}(a^2 + b^2 + c^2)$.  \boxed{\frac{a^2 + b^2 + c^2}{3}}
